<template><view class="page"><text class="title">通知设置</text><text class="sub">当前仅保存本机偏好；真实通知还需要微信订阅消息后端能力。</text><view class="card"><view v-for="item in items" :key="item.key" class="row"><view><text class="name">{{item.name}}</text><text class="desc">{{item.desc}}</text></view><switch :checked="item.enabled" color="#2fa99a" @change="onChange(item,$event)"/></view></view><button class="save" @tap="save">保存本机偏好</button></view></template><script>export default{data(){return{items:[{key:'sos',name:'紧急求助',desc:'订阅消息接入后用于紧急事件提醒',enabled:true},{key:'medicine',name:'用药提醒',desc:'订阅消息接入后用于未确认提醒',enabled:true},{key:'health',name:'健康记录',desc:'订阅消息接入后用于健康数据变化提醒',enabled:false}]}},onLoad(){const saved=uni.getStorageSync('notify_settings');if(Array.isArray(saved))this.items=this.items.map(i=>({...i,enabled:saved.find(x=>x.key===i.key)?.enabled??i.enabled}))},methods:{onChange(item,e){item.enabled=e.detail.value},save(){uni.setStorageSync('notify_settings',this.items.map(({key,enabled})=>({key,enabled})));uni.showToast({title:'已保存',icon:'success'})}}}</script><style scoped>.page{min-height:100vh;padding:30rpx;background:#fff9f2}.title{display:block;font-size:40rpx;font-weight:900;color:#493a33}.sub{display:block;margin:10rpx 0 28rpx;color:#8b786d;line-height:1.6}.card{padding:0 24rpx;background:#fff;border-radius:28rpx}.row{min-height:116rpx;display:flex;align-items:center;justify-content:space-between;border-bottom:1rpx solid #f0e7df}.row:last-child{border-bottom:none}.name,.desc{display:block}.name{font-size:25rpx;font-weight:800}.desc{margin-top:6rpx;color:#928077;font-size:19rpx}.save{margin-top:26rpx;background:#2fa99a;color:#fff;border-radius:20rpx}</style>